public class InnerDistributionTenantCustomizationsFactory(Action<Humidifier.CloudFront.DistributionTenantTypes.Customizations> factoryAction = null) : SubResourceFactory<Humidifier.CloudFront.DistributionTenantTypes.Customizations>
{

    internal InnerDistributionTenantWebAclCustomizationFactory WebAclFactory { get; set; }

    internal InnerDistributionTenantGeoRestrictionCustomizationFactory GeoRestrictionsFactory { get; set; }

    internal InnerDistributionTenantCertificateFactory CertificateFactory { get; set; }

    protected override Humidifier.CloudFront.DistributionTenantTypes.Customizations Create()
    {
        var customizationsResult = CreateCustomizations();
        factoryAction?.Invoke(customizationsResult);

        return customizationsResult;
    }

    private Humidifier.CloudFront.DistributionTenantTypes.Customizations CreateCustomizations()
    {
        var customizationsResult = new Humidifier.CloudFront.DistributionTenantTypes.Customizations();

        return customizationsResult;
    }
    public override void CreateChildren(Humidifier.CloudFront.DistributionTenantTypes.Customizations result)
    {
        base.CreateChildren(result);

        result.WebAcl ??= WebAclFactory?.Build();
        result.GeoRestrictions ??= GeoRestrictionsFactory?.Build();
        result.Certificate ??= CertificateFactory?.Build();
    }

} // End Of Class

